import {
  Component, OnInit, OnDestroy, signal, inject, ChangeDetectionStrategy, ChangeDetectorRef
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterModule } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil, debounceTime } from 'rxjs/operators';
import { ApiService } from '../../core/services/api.service';

const CONTRACT_TYPES = [
  'Option A NEC4 PSC (Service DA) Priced Contract',
  'Option C NEC4 PSC (Service DA) Target Contract',
  'Option E NEC4 PSC (Service DA) Cost Reimbursable',
  'NEC3 PSC',
  'PSSC Short Form',
];
const DELIVERY_METHODS = ['Service Delivery Agreement','Email','Hard Copy','Portal Upload'];
const LEADS = ['James Dawson','Sarah Mitchell','Priya Patel','Tom Hargreaves','Lucy Chen'];
const TOMS_OPTIONS = [
  'NT18 - Total amount (£) spent in LOCAL supply chain',
  'NT19 - Total amount (£) spent through contract with LOCAL MSMEs',
  'NT61 - Fair Payment Percentage',
  'NT17 - Jobs created or safeguarded',
  'NT62 - Apprenticeships',
];

@Component({
  selector: 'app-srp-form',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [CommonModule, RouterModule, FormsModule],
  styles: [`
    :host { display:block; font-family:inherit; }
    .srp-shell { display:flex; flex-direction:column; height:100%; background:#f0f2f7; }
    .srp-toolbar { display:flex; align-items:center; gap:8px; padding:8px 16px; background:#fff; border-bottom:1px solid #dde2ee; flex-shrink:0; }
    .srp-toolbar::before { content:''; position:absolute; left:0; right:0; top:0; height:2px; background:linear-gradient(90deg,#00aeef,#f5a800); }
    .srp-body { display:flex; flex:1; overflow:hidden; gap:0; }
    /* Stepper nav */
    .srp-stepper { width:200px; flex-shrink:0; background:#fff; border-right:1px solid #dde2ee; overflow-y:auto; padding:8px 0; }
    .step-item { display:flex; align-items:center; gap:8px; padding:8px 14px; cursor:pointer; font-size:12px; color:#5a6b8a; transition:all .12s; border-left:3px solid transparent; }
    .step-item:hover { background:#f5f7fb; color:#1a2240; }
    .step-item.active { background:rgba(37,99,235,.07); color:#2563eb; font-weight:700; border-left-color:#2563eb; }
    .step-item.complete .step-num { background:#16a34a; color:#fff; }
    .step-num { width:20px; height:20px; border-radius:50%; background:#e2e8f0; color:#64748b; font-size:10px; font-weight:700; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0; }
    /* Content */
    .srp-content { flex:1; overflow-y:auto; padding:20px; }
    .srp-section { background:#fff; border:1px solid #dde2ee; border-radius:8px; margin-bottom:14px; overflow:hidden; }
    .srp-sec-hdr { display:flex; align-items:center; gap:8px; padding:11px 16px; background:#f8fafc; border-bottom:1px solid #e2e8f0; cursor:pointer; user-select:none; }
    .srp-sec-hdr h3 { font-size:12.5px; font-weight:700; color:#1a2240; margin:0; flex:1; }
    .srp-sec-body { padding:16px; }
    .srp-grid { display:grid; grid-template-columns:1fr 1fr; gap:12px; }
    .srp-grid-3 { display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px; }
    .srp-full { grid-column:1/-1; }
    .srp-field { display:flex; flex-direction:column; gap:4px; }
    .srp-label { font-size:11px; font-weight:600; color:#5a6b8a; text-transform:uppercase; letter-spacing:.3px; }
    .srp-required::after { content:' *'; color:#dc2626; }
    .srp-input { border:1px solid #dde2ee; border-radius:6px; padding:7px 10px; font-size:12.5px; font-family:inherit; background:#fff; outline:none; transition:border-color .12s; }
    .srp-input:focus { border-color:#2563eb; box-shadow:0 0 0 3px rgba(37,99,235,.1); }
    .srp-textarea { border:1px solid #dde2ee; border-radius:6px; padding:8px 10px; font-size:12.5px; font-family:inherit; background:#fff; outline:none; resize:vertical; min-height:80px; line-height:1.5; }
    .srp-textarea:focus { border-color:#2563eb; box-shadow:0 0 0 3px rgba(37,99,235,.1); }
    .srp-select { border:1px solid #dde2ee; border-radius:6px; padding:7px 10px; font-size:12.5px; font-family:inherit; background:#fff; cursor:pointer; outline:none; }
    .srp-select:focus { border-color:#2563eb; }
    /* Yes/No toggle */
    .yn-wrap { display:flex; gap:0; border:1px solid #dde2ee; border-radius:6px; overflow:hidden; }
    .yn-btn { flex:1; padding:6px 12px; font-size:12px; font-weight:600; cursor:pointer; border:none; background:#fff; color:#64748b; transition:all .12s; font-family:inherit; }
    .yn-btn.yn-active-yes { background:#dcfce7; color:#166534; }
    .yn-btn.yn-active-no  { background:#fee2e2; color:#991b1b; }
    /* Status badge */
    .status-banner { display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:7px; margin-bottom:14px; font-size:12.5px; }
    .status-banner.draft    { background:#eff6ff; border:1px solid #bfdbfe; color:#1d4ed8; }
    .status-banner.approval { background:#fefce8; border:1px solid #fde68a; color:#92400e; }
    .status-banner.approved { background:#f0fdf4; border:1px solid #bbf7d0; color:#15803d; }
    .status-banner.rejected { background:#fef2f2; border:1px solid #fecaca; color:#b91c1c; }
    /* TOMS table */
    .toms-table { width:100%; border-collapse:collapse; font-size:12px; }
    .toms-table th { background:#f5f7fb; padding:7px 8px; font-size:10.5px; font-weight:700; text-transform:uppercase; letter-spacing:.3px; color:#5a6b8a; border-bottom:2px solid #e2e8f0; text-align:left; }
    .toms-table td { padding:6px 8px; border-bottom:1px solid #f0f2f7; vertical-align:middle; }
    .toms-table .toms-input { border:1px solid #dde2ee; border-radius:4px; padding:4px 6px; font-size:12px; font-family:inherit; background:#fff; outline:none; width:100%; }
    .toms-table .toms-input:focus { border-color:#2563eb; }
    /* Delivery table */
    .del-table { width:100%; border-collapse:collapse; font-size:12.5px; }
    .del-table th { background:#f5f7fb; padding:7px 10px; font-size:10.5px; font-weight:700; text-transform:uppercase; color:#5a6b8a; border-bottom:2px solid #e2e8f0; }
    .del-table td { padding:6px 8px; border-bottom:1px solid #f0f2f7; }
    /* Buttons */
    .btn { display:inline-flex; align-items:center; gap:5px; padding:7px 16px; border-radius:7px; border:1px solid transparent; cursor:pointer; font-size:12.5px; font-weight:600; font-family:inherit; transition:all .12s; }
    .btn-primary { background:#2563eb; color:#fff; border-color:#2563eb; }
    .btn-primary:hover { background:#1d4ed8; }
    .btn-success { background:#16a34a; color:#fff; border-color:#16a34a; }
    .btn-success:hover { background:#15803d; }
    .btn-danger  { background:#dc2626; color:#fff; border-color:#dc2626; }
    .btn-ghost   { background:#fff; color:#5a6b8a; border-color:#dde2ee; }
    .btn-ghost:hover { background:#f5f7fb; }
    .btn-sm { padding:5px 12px; font-size:12px; }
    .save-indicator { font-size:11px; color:#16a34a; opacity:0; transition:opacity .3s; }
    .save-indicator.show { opacity:1; }
    .chip { display:inline-block; padding:2px 8px; border-radius:10px; background:rgba(37,99,235,.08); color:#1d4ed8; font-size:10.5px; font-weight:600; }
    .badge { display:inline-block; padding:3px 10px; border-radius:10px; font-size:11px; font-weight:700; }
    .badge-blue { background:#dbeafe; color:#1d4ed8; }
    .badge-amber { background:#fef3c7; color:#92400e; }
    .badge-green { background:#dcfce7; color:#166534; }
    .badge-red { background:#fee2e2; color:#991b1b; }
    .text-muted { color:#64748b; font-size:12px; }
    /* Progress bar */
    .srp-progress { display:flex; gap:4px; margin-bottom:12px; }
    .srp-progress-seg { flex:1; height:4px; border-radius:2px; background:#e2e8f0; transition:background .3s; }
    .srp-progress-seg.filled { background:#2563eb; }
  `],
  template: `
  <div class="srp-shell">
    <!-- Toolbar -->
    <div class="srp-toolbar" style="position:relative">
      <a routerLink="/opportunities" style="font-size:12px;color:#64748b;text-decoration:none">← Back</a>
      <span class="chip" *ngIf="opp">{{ opp?.commNum }}</span>
      <span style="font-size:13px;font-weight:700;color:#1a2240">{{ opp?.name }}</span>
      <span class="badge" [class]="statusBadge">{{ srp?.status || 'Draft' }}</span>
      <div style="margin-left:auto;display:flex;gap:6px;align-items:center">
        <span class="save-indicator" [class.show]="saved">✓ Saved</span>
        <button class="btn btn-ghost btn-sm" (click)="saveDraft()">💾 Save Draft</button>
        <button class="btn btn-primary btn-sm" *ngIf="srp?.status==='Draft'" (click)="sendForApproval()" [disabled]="!mandatoryComplete">
          Send for Approval
        </button>
        <button class="btn btn-success btn-sm" *ngIf="srp?.status==='SentForApproval'" (click)="approve()">✓ Approve</button>
        <button class="btn btn-danger btn-sm" *ngIf="srp?.status==='SentForApproval'" (click)="reject()">✕ Reject</button>
        <button class="btn btn-ghost btn-sm" (click)="printSRP()">🖨 Print</button>
      </div>
    </div>

    <div class="srp-body">
      <!-- Stepper nav -->
      <nav class="srp-stepper" aria-label="SRP sections">
        <div class="srp-progress">
          <div class="srp-progress-seg" *ngFor="let _ of steps" [class.filled]="progressPct > 0"></div>
        </div>
        <div *ngFor="let step of steps; let i=index"
          class="step-item"
          [class.active]="activeStep===i"
          [class.complete]="isStepComplete(i)"
          (click)="activeStep=i"
          [attr.aria-label]="step.label"
          role="button" tabindex="0"
          (keydown.enter)="activeStep=i">
          <span class="step-num">{{ i+1 }}</span>
          <span>{{ step.label }}</span>
        </div>
      </nav>

      <!-- Main content -->
      <div class="srp-content" id="srp-scroll-area">

        <!-- Status banner -->
        <div class="status-banner" [class]="statusBannerClass" *ngIf="srp">
          <span>{{ statusIcon }}</span>
          <strong>{{ srp.status || 'Draft' }}</strong>
          <span *ngIf="srp.status==='SentForApproval'">— Awaiting approval from commercial lead</span>
          <span *ngIf="srp.status==='Approved'">— Approved by {{ srp.approvedBy }} on {{ srp.approvedAt | date:'dd MMM yyyy' }}</span>
          <span *ngIf="srp.status==='Rejected'">— {{ srp.approvalComments }}</span>
          <span *ngIf="!mandatoryComplete && srp.status==='Draft'" style="margin-left:auto;font-size:11px;color:#dc2626">⚠ Complete mandatory fields to send for approval</span>
        </div>

        <div *ngIf="!srp" style="text-align:center;padding:40px;color:#94a3b8">Loading SRP data…</div>

        <ng-container *ngIf="srp">

        <!-- ── PART A: Outline Service Requirements ─────────────────── -->
        <div *ngIf="activeStep===0">
          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('contacts')">
              <h3>1.0 — Commission & Contact Details</h3>
              <span>{{ collapsed['contacts'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['contacts']">
              <div class="srp-grid">
                <div class="srp-field">
                  <label class="srp-label srp-required">Client Contact Name</label>
                  <input class="srp-input" [(ngModel)]="srp.clientContactName" placeholder="Full name" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label srp-required">Commission Lead</label>
                  <select class="srp-select" [(ngModel)]="srp.commissionLead" (ngModelChange)="autoSave()">
                    <option value="">— Select —</option>
                    <option *ngFor="let l of leads" [value]="l">{{ l }}</option>
                  </select>
                </div>
                <div class="srp-field">
                  <label class="srp-label">Client Contact Email</label>
                  <input class="srp-input" type="email" [(ngModel)]="srp.clientContactEmail" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">Commission Lead Email</label>
                  <input class="srp-input" type="email" [(ngModel)]="srp.commissionLeadEmail" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">Client Contact Tel</label>
                  <input class="srp-input" [(ngModel)]="srp.clientContactTel" maxlength="50" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">Commission Lead Mobile</label>
                  <input class="srp-input" [(ngModel)]="srp.commissionLeadMobile" maxlength="50" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">Client Contact Position</label>
                  <input class="srp-input" [(ngModel)]="srp.clientContactPosition" placeholder="Role / position" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label srp-required">Service Manager</label>
                  <input class="srp-input" [(ngModel)]="srp.serviceManager" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field srp-full">
                  <label class="srp-label srp-required">Commission Description</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.commissionDesc" placeholder="Brief description of the commission…" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field">
                  <label class="srp-label">Commission Post Code</label>
                  <input class="srp-input" [(ngModel)]="srp.commissionPostCode" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label srp-required">Main Contract Type</label>
                  <select class="srp-select" [(ngModel)]="srp.mainContractType" (ngModelChange)="autoSave()">
                    <option value="">— Select —</option>
                    <option *ngFor="let c of contractTypes" [value]="c">{{ c }}</option>
                  </select>
                </div>
                <div class="srp-field">
                  <label class="srp-label">Start Date</label>
                  <input class="srp-input" type="date" [(ngModel)]="srp.startDate" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">End Date</label>
                  <input class="srp-input" type="date" [(ngModel)]="srp.endDate" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">Confidentiality Flag</label>
                  <div class="yn-wrap">
                    <button class="yn-btn" [class.yn-active-yes]="srp.confidentialityFlag==='Yes'" (click)="srp.confidentialityFlag='Yes';autoSave()">Yes</button>
                    <button class="yn-btn" [class.yn-active-no]="srp.confidentialityFlag==='No'" (click)="srp.confidentialityFlag='No';autoSave()">No</button>
                  </div>
                </div>
                <div class="srp-field">
                  <label class="srp-label">Has Programme?</label>
                  <div class="yn-wrap">
                    <button class="yn-btn" [class.yn-active-yes]="srp.hasProgramme==='Yes'" (click)="srp.hasProgramme='Yes';autoSave()">Yes</button>
                    <button class="yn-btn" [class.yn-active-no]="srp.hasProgramme==='No'" (click)="srp.hasProgramme='No';autoSave()">No</button>
                  </div>
                </div>
                <div class="srp-field">
                  <label class="srp-label">Has Project Brief?</label>
                  <div class="yn-wrap">
                    <button class="yn-btn" [class.yn-active-yes]="srp.hasProjectBrief==='Yes'" (click)="srp.hasProjectBrief='Yes';autoSave()">Yes</button>
                    <button class="yn-btn" [class.yn-active-no]="srp.hasProjectBrief==='No'" (click)="srp.hasProjectBrief='No';autoSave()">No</button>
                  </div>
                </div>
                <div class="srp-field">
                  <label class="srp-label">Has Scheme Layout?</label>
                  <div class="yn-wrap">
                    <button class="yn-btn" [class.yn-active-yes]="srp.hasSchemeLayout==='Yes'" (click)="srp.hasSchemeLayout='Yes';autoSave()">Yes</button>
                    <button class="yn-btn" [class.yn-active-no]="srp.hasSchemeLayout==='No'" (click)="srp.hasSchemeLayout='No';autoSave()">No</button>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Part B: Pre-Engagement -->
          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('preeng')">
              <h3>2.0 — Pre-Engagement Requirements</h3>
              <span>{{ collapsed['preeng'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['preeng']">
              <div class="srp-field" style="margin-bottom:12px">
                <label class="srp-label">Pre-Engagement Required?</label>
                <div class="yn-wrap" style="max-width:200px">
                  <button class="yn-btn" [class.yn-active-yes]="srp.preEngagementRequired==='Yes'" (click)="srp.preEngagementRequired='Yes';autoSave()">Yes</button>
                  <button class="yn-btn" [class.yn-active-no]="srp.preEngagementRequired==='No'" (click)="srp.preEngagementRequired='No';autoSave()">No</button>
                </div>
              </div>
              <div *ngIf="srp.preEngagementRequired==='Yes'" style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:7px;padding:12px">
                <p style="font-size:12px;color:#1d4ed8;margin-bottom:8px">Specify pre-engagement requirements the client must satisfy before commission commences:</p>
                <textarea class="srp-textarea" [(ngModel)]="srp.s61" placeholder="Detail pre-engagement activities…" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
            </div>
          </div>
        </div>

        <!-- ── PART C: Project Overview & VfM ──────────────────────── -->
        <div *ngIf="activeStep===1">
          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('overview')">
              <h3>3.0 — Project Overview & Objectives</h3>
              <span>{{ collapsed['overview'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['overview']">
              <div class="srp-field" style="margin-bottom:12px">
                <label class="srp-label srp-required">Project Overview</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.projectOverview" rows="6" (ngModelChange)="autoSave()"
                  placeholder="This project is to deliver [project description] at [project location]…"></textarea>
              </div>
              <div class="srp-field" style="margin-bottom:12px">
                <label class="srp-label">Objectives</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.objectives" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-field">
                <label class="srp-label">Health & Safety</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.healthSafety" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
            </div>
          </div>

          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('vfm')">
              <h3>4.0 — Value for Money & Key Performance Indicators</h3>
              <span>{{ collapsed['vfm'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['vfm']">
              <div class="srp-field" style="margin-bottom:12px">
                <label class="srp-label">VfM Statement</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.vfmStatement" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-grid-3" style="margin-bottom:12px">
                <div class="srp-field">
                  <label class="srp-label">VfM Driver 1</label>
                  <input class="srp-input" [(ngModel)]="srp.vfmDriver1" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">VfM Driver 2</label>
                  <input class="srp-input" [(ngModel)]="srp.vfmDriver2" (ngModelChange)="autoSave()">
                </div>
                <div class="srp-field">
                  <label class="srp-label">VfM Driver 3</label>
                  <input class="srp-input" [(ngModel)]="srp.vfmDriver3" (ngModelChange)="autoSave()">
                </div>
              </div>
              <div class="srp-field">
                <label class="srp-label srp-required">Project Success Criteria</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.projectSuccessCriteria" rows="6" (ngModelChange)="autoSave()"></textarea>
              </div>
            </div>
          </div>

          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('social')">
              <h3>5.0 — Social Value (TOMS)</h3>
              <span>{{ collapsed['social'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['social']">
              <div class="srp-field" style="margin-bottom:12px">
                <label class="srp-label">Social Value Narrative</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.socialValue" rows="3" (ngModelChange)="autoSave()"></textarea>
              </div>
              <table class="toms-table">
                <thead><tr>
                  <th style="width:35%">TOMS Reference</th>
                  <th>Comments</th>
                  <th style="width:60px">Unit</th>
                  <th style="width:80px">SV Proxy</th>
                  <th style="width:80px">Target</th>
                  <th style="width:80px">SV Add</th>
                </tr></thead>
                <tbody>
                  <tr *ngFor="let row of srp.tomsRows; let i=index">
                    <td>
                      <span *ngIf="i<3" style="font-size:11px;color:#64748b">{{ row.ref }}</span>
                      <select *ngIf="i>=3" class="toms-input" [(ngModel)]="row.ref" (ngModelChange)="autoSave()">
                        <option value="Please Select">Please Select</option>
                        <option *ngFor="let o of tomsOptions" [value]="o">{{ o }}</option>
                      </select>
                    </td>
                    <td><textarea class="toms-input" [(ngModel)]="row.comments" rows="2" (ngModelChange)="autoSave()"></textarea></td>
                    <td>{{ row.unit }}</td>
                    <td>{{ row.svProxy | number:'1.2-2' }}</td>
                    <td><input class="toms-input" type="number" [(ngModel)]="row.target" step="0.01" min="0" (ngModelChange)="autoSave()" style="text-align:right"></td>
                    <td style="text-align:right;font-weight:700;color:#2563eb">{{ (row.target * row.svProxy) | number:'1.2-2' }}</td>
                  </tr>
                </tbody>
                <tfoot>
                  <tr style="background:#f8fafc">
                    <td colspan="5" style="text-align:right;font-weight:700;font-size:12px;padding:8px">Total Social Value Added:</td>
                    <td style="text-align:right;font-weight:800;font-size:13px;color:#16a34a;padding:8px">{{ tomsTotal | number:'1.2-2' }}</td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        </div>

        <!-- ── Scope of Services ───────────────────────────────────── -->
        <div *ngIf="activeStep===2">
          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('scope6')">
              <h3>6.0 — Scope of Services</h3>
              <span>{{ collapsed['scope6'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['scope6']">
              <div class="srp-field" style="margin-bottom:14px">
                <label class="srp-label">6.1 — Professional Services Schedule</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.s61" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-field" style="margin-bottom:14px">
                <label class="srp-label">6.2 — Scope Addendum</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.s62" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-field" style="margin-bottom:14px">
                <label class="srp-label">6.3 — Additional Scope Notes</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.s63" rows="3" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-field" style="margin-bottom:14px">
                <label class="srp-label">6.5 — Health & Safety (CDM)</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.s65" rows="3" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-field" style="margin-bottom:14px">
                <label class="srp-label">6.6 — Principal Designer</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.s66" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>
              <div class="srp-field">
                <label class="srp-label">7.0 — Key Staff CVs</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.s70" rows="3" (ngModelChange)="autoSave()"></textarea>
              </div>
            </div>
          </div>

          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('scope9')">
              <h3>9.0 – 15.0 — Extended Scope Sections</h3>
              <span>{{ collapsed['scope9'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['scope9']">
              <div class="srp-grid" style="gap:14px">
                <div class="srp-field">
                  <label class="srp-label">9.0 — Insurance Requirements</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s90" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field">
                  <label class="srp-label">10.0 — Payment Terms</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s100" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field">
                  <label class="srp-label">11.0 — Quality Management</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s110" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field">
                  <label class="srp-label">12.0 — Sustainability</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s120" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field">
                  <label class="srp-label">13.0 — BIM Requirements</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s130" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field">
                  <label class="srp-label">14.0 — Reporting Requirements</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s140" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
                <div class="srp-field srp-full">
                  <label class="srp-label">15.0 — Additional Requirements</label>
                  <textarea class="srp-textarea" [(ngModel)]="srp.s150" rows="3" (ngModelChange)="autoSave()"></textarea>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- ── Programme ──────────────────────────────────────────── -->
        <div *ngIf="activeStep===3">
          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('prog')">
              <h3>8.0 — Programme</h3>
              <span>{{ collapsed['prog'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['prog']">
              <div class="srp-field" style="margin-bottom:12px">
                <label class="srp-label">Upload Own Programme?</label>
                <div class="yn-wrap" style="max-width:200px">
                  <button class="yn-btn" [class.yn-active-yes]="srp.uploadOwnProgramme==='Yes'" (click)="srp.uploadOwnProgramme='Yes';autoSave()">Yes</button>
                  <button class="yn-btn" [class.yn-active-no]="srp.uploadOwnProgramme==='No'" (click)="srp.uploadOwnProgramme='No';autoSave()">No</button>
                </div>
              </div>
              <div *ngIf="srp.uploadOwnProgramme==='No'">
                <p style="font-size:12px;color:#5a6b8a;margin-bottom:10px">Define the delivery programme for each RIBA stage:</p>
                <table class="del-table">
                  <thead><tr>
                    <th>RIBA Stage</th><th>Activity</th>
                    <th style="width:130px">Start Date</th><th style="width:130px">End Date</th>
                  </tr></thead>
                  <tbody>
                    <tr *ngFor="let row of srp.deliveryRows">
                      <td style="font-weight:600;color:#1a2240">{{ row.stage }}</td>
                      <td><input class="srp-input" [(ngModel)]="row.activity" (ngModelChange)="autoSave()"></td>
                      <td><input class="srp-input" type="date" [(ngModel)]="row.startDate" (ngModelChange)="autoSave()"></td>
                      <td><input class="srp-input" type="date" [(ngModel)]="row.endDate" (ngModelChange)="autoSave()"></td>
                    </tr>
                  </tbody>
                </table>
              </div>
              <div *ngIf="srp.uploadOwnProgramme==='Yes'" style="padding:16px;background:#f8fafc;border:1px dashed #dde2ee;border-radius:7px;text-align:center;color:#94a3b8">
                Programme upload functionality — attach programme document via document management system
              </div>
            </div>
          </div>
        </div>

        <!-- ── Approval ──────────────────────────────────────────── -->
        <div *ngIf="activeStep===4">
          <div class="srp-section">
            <div class="srp-sec-hdr" (click)="toggle('approval')">
              <h3>Approval & Sign-off</h3>
              <span>{{ collapsed['approval'] ? '▶' : '▼' }}</span>
            </div>
            <div class="srp-sec-body" *ngIf="!collapsed['approval']">
              <div class="srp-grid" style="margin-bottom:14px">
                <div class="srp-field">
                  <label class="srp-label srp-required">SRP Delivery Method</label>
                  <select class="srp-select" [(ngModel)]="srp.srpDeliveryMethod" (ngModelChange)="autoSave()">
                    <option value="">— Select —</option>
                    <option *ngFor="let d of deliveryMethods" [value]="d">{{ d }}</option>
                  </select>
                </div>
                <div class="srp-field">
                  <label class="srp-label srp-required">Commercial Lead</label>
                  <select class="srp-select" [(ngModel)]="srp.commercialLead" (ngModelChange)="autoSave()">
                    <option value="">— Select —</option>
                    <option *ngFor="let l of leads" [value]="l">{{ l }}</option>
                  </select>
                </div>
              </div>
              <div class="srp-field" *ngIf="srp.status==='SentForApproval' || srp.status==='Rejected'">
                <label class="srp-label">Approval Comments</label>
                <textarea class="srp-textarea" [(ngModel)]="srp.approvalComments" rows="4" (ngModelChange)="autoSave()"></textarea>
              </div>

              <!-- Approval actions -->
              <div style="display:flex;gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid #e2e8f0" *ngIf="srp.status!=='Approved'">
                <button class="btn btn-primary" *ngIf="srp.status==='Draft'" (click)="sendForApproval()" [disabled]="!mandatoryComplete">
                  Send for Approval
                </button>
                <button class="btn btn-success" *ngIf="srp.status==='SentForApproval'" (click)="approve()">✓ Approve SRP</button>
                <button class="btn btn-danger" *ngIf="srp.status==='SentForApproval'" (click)="reject()">✕ Reject</button>
              </div>
              <div *ngIf="srp.status==='Approved'" style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:7px;padding:14px">
                <p style="font-size:13px;font-weight:700;color:#15803d">✓ SRP Approved</p>
                <p class="text-muted" style="margin-top:4px">Approved by {{ srp.approvedBy }} on {{ srp.approvedAt | date:'dd MMM yyyy HH:mm' }}</p>
              </div>
            </div>
          </div>
        </div>

        </ng-container>

        <!-- Navigation buttons -->
        <div style="display:flex;justify-content:space-between;margin-top:16px" *ngIf="srp">
          <button class="btn btn-ghost" (click)="prevStep()" [disabled]="activeStep===0">← Previous</button>
          <button class="btn btn-primary" (click)="nextStep()" *ngIf="activeStep < steps.length-1">Next →</button>
          <button class="btn btn-success" (click)="saveDraft()" *ngIf="activeStep===steps.length-1">✓ Save</button>
        </div>
      </div>
    </div>
  </div>
  `,
})
export class SrpFormComponent implements OnInit, OnDestroy {
  private readonly api = inject(ApiService);
  private readonly route = inject(ActivatedRoute);
  private readonly cdr = inject(ChangeDetectorRef);
  private readonly destroy$ = new Subject<void>();
  private readonly save$ = new Subject<void>();

  opp: any = null;
  srp: any = null;
  activeStep = 0;
  saved = false;
  collapsed: Record<string, boolean> = {};

  readonly contractTypes = CONTRACT_TYPES;
  readonly deliveryMethods = DELIVERY_METHODS;
  readonly leads = LEADS;
  readonly tomsOptions = TOMS_OPTIONS;
  readonly steps = [
    { label: 'Part A — Details' },
    { label: 'Part C — Overview & VfM' },
    { label: 'Scope of Services' },
    { label: 'Programme' },
    { label: 'Approval' },
  ];

  get mandatoryComplete(): boolean {
    if (!this.srp) return false;
    return !!(
      this.srp.clientContactName &&
      this.srp.commissionLead &&
      this.srp.serviceManager &&
      this.srp.commissionDesc &&
      this.srp.mainContractType &&
      this.srp.projectOverview &&
      this.srp.projectSuccessCriteria &&
      this.srp.srpDeliveryMethod &&
      this.srp.commercialLead
    );
  }

  get progressPct(): number {
    if (!this.srp) return 0;
    const fields = [
      this.srp.clientContactName, this.srp.commissionLead, this.srp.serviceManager,
      this.srp.commissionDesc, this.srp.mainContractType, this.srp.projectOverview,
      this.srp.projectSuccessCriteria, this.srp.srpDeliveryMethod, this.srp.commercialLead,
    ];
    return Math.round(fields.filter(Boolean).length / fields.length * 100);
  }

  get tomsTotal(): number {
    return (this.srp?.tomsRows || []).reduce((a: number, r: any) => a + (r.target * r.svProxy), 0);
  }

  get statusBadge(): string {
    return { Draft:'badge-blue', SentForApproval:'badge-amber', Approved:'badge-green', Rejected:'badge-red' }[this.srp?.status] || 'badge-blue';
  }
  get statusBannerClass(): string {
    return { Draft:'draft', SentForApproval:'approval', Approved:'approved', Rejected:'rejected' }[this.srp?.status] || 'draft';
  }
  get statusIcon(): string {
    return { Draft:'📝', SentForApproval:'⏳', Approved:'✅', Rejected:'❌' }[this.srp?.status] || '📝';
  }

  ngOnInit() {
    const id = this.route.snapshot.paramMap.get('id')!;
    this.api.get<any>(`/v1/opportunities/${id}`).subscribe(o => {
      this.opp = o;
      this.api.get<any>(`/v1/srp/${id}`).subscribe(s => {
        // Ensure tomsRows and deliveryRows exist
        if (!s.tomsRows || !s.tomsRows.length) {
          s.tomsRows = [
            {ref:'NT18 - Total amount (£) spent in LOCAL supply chain through the contract',comments:'',unit:'£',svProxy:0.91,target:0,svAdd:0},
            {ref:'NT19 - Total amount (£) spent through contract with LOCAL MSMEs',comments:'',unit:'£',svProxy:0.91,target:0,svAdd:0},
            {ref:'NT61 - Fair Payment - Percentage of invoices on the contract paid within 30 days',comments:'',unit:'%',svProxy:0.00,target:100,svAdd:0},
            {ref:'Please Select',comments:'',unit:'£',svProxy:0.00,target:0,svAdd:0},
            {ref:'Please Select',comments:'',unit:'£',svProxy:0.00,target:0,svAdd:0},
            {ref:'Please Select',comments:'',unit:'£',svProxy:0.00,target:0,svAdd:0},
            {ref:'Please Select',comments:'',unit:'£',svProxy:0.00,target:0,svAdd:0},
            {ref:'Please Select',comments:'',unit:'£',svProxy:0.00,target:0,svAdd:0},
          ];
        }
        if (!s.deliveryRows || !s.deliveryRows.length) {
          s.deliveryRows = [
            {stage:'Stage 2',activity:'Concept Design',startDate:'',endDate:''},
            {stage:'Stage 3',activity:'Spatial Coordination',startDate:'',endDate:''},
            {stage:'Stage 4',activity:'Technical Design',startDate:'',endDate:''},
            {stage:'Stage 5',activity:'Construction',startDate:'',endDate:''},
          ];
        }
        this.srp = s;
        this.cdr.markForCheck();
      });
    });

    // Debounced auto-save
    this.save$.pipe(debounceTime(1500), takeUntil(this.destroy$)).subscribe(() => this.doSave());
  }

  ngOnDestroy() { this.destroy$.next(); this.destroy$.complete(); }

  toggle(key: string) { this.collapsed[key] = !this.collapsed[key]; }
  isStepComplete(i: number): boolean { return i === 0 && !!(this.srp?.clientContactName && this.srp?.commissionLead); }
  prevStep() { if (this.activeStep > 0) { this.activeStep--; this.scrollTop(); } }
  nextStep() { if (this.activeStep < this.steps.length - 1) { this.activeStep++; this.scrollTop(); } }
  scrollTop() { document.getElementById('srp-scroll-area')?.scrollTo(0, 0); }

  autoSave() { this.save$.next(); }

  saveDraft() { this.doSave(); }

  private doSave() {
    if (!this.srp || !this.opp) return;
    this.api.put(`/v1/srp/${this.opp.id}`, this.srp).subscribe(() => {
      this.saved = true;
      this.cdr.markForCheck();
      setTimeout(() => { this.saved = false; this.cdr.markForCheck(); }, 2500);
    });
  }

  sendForApproval() {
    if (!this.opp) return;
    this.doSave();
    this.api.post(`/v1/srp/${this.opp.id}/send-approval`, {}).subscribe(() => {
      this.srp = { ...this.srp, status: 'SentForApproval' };
      this.cdr.markForCheck();
    });
  }

  approve() {
    if (!this.opp) return;
    const comments = this.srp.approvalComments || 'Approved';
    this.api.post(`/v1/srp/${this.opp.id}/approve`, { comments }).subscribe(() => {
      this.srp = { ...this.srp, status: 'Approved', approvedAt: new Date().toISOString() };
      this.cdr.markForCheck();
    });
  }

  reject() {
    if (!this.opp) return;
    const comments = this.srp.approvalComments || 'Rejected';
    this.api.post(`/v1/srp/${this.opp.id}/reject`, { comments }).subscribe(() => {
      this.srp = { ...this.srp, status: 'Rejected' };
      this.cdr.markForCheck();
    });
  }

  printSRP() { window.print(); }
  trkIdx(i: number) { return i; }

}
